from dataclasses import dataclass

@dataclass(frozen=True)
class RetryWindow:
    base: int
    cap: int

def RetryWindow_pause(self: RetryWindow, attempt: int) -> int:
    if attempt < 0:
        raise ValueError('attempt must be nonnegative')
    if attempt == 0:
        return self.base
    if self.cap // self.base < 2:
        return self.cap
    return self.base * 2
